    private static Map<String,Object> toMap(JSONObject value)throws Exception{Map<String,Object> result=new LinkedHashMap<>();Iterator<String> keys=value.keys();while(keys.hasNext()){String key=keys.next();result.put(key,javaValue(value.get(key)));}return result;}
